import fp from 'fastify-plugin';
import swagger from '@fastify/swagger';
import swaggerUi from '@fastify/swagger-ui';

import { NODE_DATA } from './discovery.js';

/**
 * The API description: an OpenAPI 3.1 document generated by `@fastify/swagger`
 * from the route schemas, so it describes the routes that exist. Served raw at
 * `/api/v1/openapi.json` (the version index's `service-desc`) and through
 * Swagger UI at `/api/v1/docs`, which also serves it at `/api/v1/docs/json`.
 * Neither is enveloped, and both are hidden from the document and discovery.
 *
 * Routes marked `schema.hide` are left out: stub writes, taxa's 405s, every
 * `specimens` route. Components are named by their `$id` (`Collection`,
 * `ReferenceLink`, …: lib/published-schemas.js), not `def-0`.
 *
 * This must load before any documented route, discovery's included, since
 * `@fastify/swagger` collects routes as they are added: discovery depends on
 * it by name.
 */

const VERSION = '/api/v1';

export default fp(
  async (fastify) => {
    const node = NODE_DATA[VERSION];

    await fastify.register(swagger, {
      openapi: {
        openapi: '3.1.0',
        info: { title: node.name, version: node.version, description: node.description },
        servers: [{ url: fastify.publicBaseUrl }],
      },
      refResolver: {
        buildLocalReference: (json, _baseUri, _fragment, i) => json.$id || `def-${i}`,
      },
    });

    await fastify.register(swaggerUi, { routePrefix: `${VERSION}/docs` });

    fastify.get(`${VERSION}/openapi.json`, { schema: { hide: true } }, async () => fastify.swagger());
  },
  { name: 'openapi' },
);
